def render_top_nav(active: str) -> None:
    items=[("home","Home"),("strategy","Strategy Lab"),("evidence","Evidence Lab"),("mmm","Marketing Mix Model"),("directory","Analytics Directory"),("about","Behind the Lab")]
    links=[]
    for slug,label in items:
        klass="active" if slug==active else ""
        links.append(f'<a class="{klass}" href="?page={slug}" target="_self">{label}</a>')
    st.markdown('<div class="cl-top-nav">'+''.join(links)+'</div>',unsafe_allow_html=True)


def kicker(text: str) -> None:
    st.markdown(f'<div class="campaignlab-kicker">{text}</div>',unsafe_allow_html=True)
